WFJ.Data.add("gossip", {
  ["4d007232c5f0188c"] = { "Un tempo questa gemma permetteva di comunicare direttamente con Elune in persona.", "." },
  ["4d04fa60ba627775"] = { "Vedo che ti senti meglio.", "." },
  ["4d071067108bba79"] = { "Ehi... Ehi... Aaaaahhh!", "." },
  ["4d0d539fb7727b37"] = { "Non tollereremo nessun servo dei demoni nelle nostre terre!", "." },
  ["4d107654a72ab679"] = { "Salute. Sono ⟦Chronos=Cronos⟧, Colui che Non Dimentica Mai. La mia memoria è infallibile, precisa fino al più piccolo dettaglio.\n\nFidati.", "." },
  ["4d112de1b68c70b8"] = { "Ottimo lavoro! Ci siamo quasi, {name}. Da questa parte.", "." },
  ["4d16eb50708d21a6"] = { "Guardie, ai vostri posti! Devono essere di nuovo a caccia del magistrato. Va protetto! Potrebbero arrivare da qualsiasi direzione!", "." },
  ["4d193aae0ab6c2c3"] = { "Ebbene sì, conosco una rara ricetta alchemica. Lascia che te la insegni!", "." },
  ["4d1b277577e5b348"] = { "Kalaran, ti prego, incanta la torcia.", "." },
  ["4d2c77e6cf39ee31"] = { "Voglio comprendere l'importanza della forza del corpo.", "." },
  ["4d2f86d3857825b6"] = { "Ehilà, {name}! Non è un bello spettacolo, vero?\n\nLa Horizon Scout in fondo al mare, la mia ciurma allo sbando, e il carico e i passeggeri sparpagliati come tanti detriti, che sembra uno dei canali di Roccavento dopo una festa.\n\nE i guai non finiscono qui...", "." },
  ["4d3b5e4cab776fc7"] = { "Raccogli le bacche dallo sbocciavento.", "." },
  ["4d3e9a39a5d058a8"] = { "La ⟦Scarlet Crusade=Crociata Scarlatta⟧ sta invadendo la nostra patria. Quegli stolti fanatici non si rendono conto che i fedeli servitori della Dama Oscura provvederanno alla loro fine.", "." },
  ["4d3fafb53a893492"] = { "Il caldo... non lo sopporto...", "." },
  ["4d45327417523a79"] = { "Non puoi nasconderti da noi. Preparati a bruciare!", "." },
  ["4d47d6d303e1429f"] = { "Per tutti gli gnomi contaminati saltellanti! Per mesi non c'è stato verso di uscire da lì. Grazie, ragazzi.", "." },
  ["4d4ac7b5ae964df2"] = { "Ah! Le mie ferite sono troppo gravi. Difensori, continuate a combattere senza di me!", "." },
  ["4d4e0169d03360e4"] = { "Credo che i Reietti stiano ingannando gli alleati dell'⟦Horde=Orda⟧.... aspetta... mi gira... la testa...", "." },
  ["4d55bcc066f22ce1"] = { "Non sono <un/una> cultista, mostro! Vieni a me e affronta la tua distruzione!", "." },
  ["4d56b2876bf9cd30"] = { "Spraggle! Non credevo che ce l'avrei fatta a tornare!", "." },
  ["4d571c511681130c"] = { "Gremlock non ha sempre fortuna in cucina, ma ha qualche ricetta gustosa che vale la pena imparare. Vai a fare due chiacchiere con lui nella ⟦Thunderbrew Distillery=Distilleria Birratuono⟧ e vedi cosa ti insegna.", "." },
  ["4d582b9220b8842e"] = { "Una corruzione contamina la nostra foresta sacra.", "." },
  ["4d5d72731075da34"] = { "Difendi ⟦Nighthaven=Nottequieta⟧, eroe...", "." },
  ["4d6175fdcc41fd8c"] = { "Quanti rifornimenti servono ancora per ricostruire la nostra base?", "." },
  ["4d61f3fb2c7ea95a"] = { "Ehm, sto portando davanti al re dei prigionieri che abbiamo trovato fuori, perché vengano puniti.", "." },
  ["4d6878b7e21685e1"] = { "Dove vuoi andare, <ragazzo/ragazza>? Per poche monete i miei grifoni ti ci portano più in fretta del più veloce dei cavalli.", "." },
  ["4d687b0e9dc160e5"] = { "Puoi dirmi cosa sta succedendo sull'⟦Zephras Isle=Isola di Zephras⟧?", "." },
  ["4d7881b4ca71190d"] = { "Le migliori bevute di ⟦Stormwind=Roccavento⟧!", "." },
  ["4d7db1bef187fe8f"] = { "Credo... credo che stia funzionando!", "." },
  ["4d8246eec5539370"] = { "Ora dobbiamo solo liberare Tobias e poi possiamo andarcene da qui. Da questa parte!", "." },
  ["4d957417274108f7"] = { "Durtham Greldon, laggiù nella Caverna degli Inganni, può insegnarti tutti i trucchi dello scasso. Solo non metterti a fare pratica con quei trucchi qui a ⟦Ironforge=Forgiardente⟧, se capisci cosa intendo.", "." },
  ["4da2f5f1886cfb4f"] = { "Ah, la dolce aria salmastra di ⟦Ratchet=Porto Paranco⟧.", "." },
  ["4da665cde68807ff"] = { "⟦Brother Wilhelm=Fratello Wilhelm⟧ si allena spesso con Lyria Du Lac, nel retro della fucina di ⟦Goldshire=Borgodoro⟧. Da lui potresti imparare un paio di cose su come essere un paladino.", "." },
  ["4daf2bd21f055cbc"] = { "(Continua.)", "." },
  ["4db04a27d0a5013a"] = { "Niente birra adesso! La corsa sta per cominciare.", "." },
  ["4db63b4ef13a4afe"] = { "Mi dispiace, ora ho un po' da fare: sto forgiando ferri di cavallo per Verner Osgood di ⟦Lakeshire=Borgolago⟧.", "." },
  ["4dbae4a5db4dad1a"] = { "Ho sentito una storia su questo pesce d'oro: se lo peschi, hai diritto a tre desideri!", "." },
  ["4dbf63edca3bc2b2"] = { "I clan dei centauri dominano le lande di ⟦Desolace=Desolanda⟧. Se fossero uniti, sarebbero una forza terribile. È un bene, quindi, che i clan dei centauri non siano uniti, ma litighino e si facciano guerra tra loro.", "." },
  ["4dc8864890324e18"] = { "Dammi retta! Non troverai grifoni più veloci in tutti i Regni Orientali di quelli qui a Thelsamar!", "." },
  ["4dcbe7be52b1a1eb"] = { "Ah, {name}, non piangere. Per tua fortuna, l'ultima volta che mi hai dato l'amuleto ho stretto un legame con esso. Lo richiamerò da dovunque tu l'abbia lasciato cadere.\n\nProva a guardare nelle tue borse adesso.", "." },
  ["4dcd940489944bcf"] = { "Fai attenzione, {name}. A quei lupi piace nascondersi fra gli alberi.", "." },
  ["4dd0eb89c5ee90aa"] = { "Ma certo, {name}. Hai l'aria di una persona fidata... Affidabile! Lo capisco a un miglio di distanza...\n\nComunque, tornando a quello che dicevo. Per fare l'⟦Videre Elixir=Elisir Videre⟧ serve una pianta di Evoroot. Il resto degli ingredienti è roba da poco, davvero, ma l'Evoroot, beh, quella può essere un po' difficile da trovare.", "." },
  ["4dde5c252191bbbc"] = { "Ecco, {name}. Prendi un Forziere di Casse di Contenimento e un Canto della Manifestazione. Ti serviranno per la tua missione.", "." },
  ["4ddfdb6bd4d3ec3a"] = { "Ti ha mandato giù da me la mia dolce Kali? È la luce dei miei occhi.", "." },
  ["4dec125cbdbcef82"] = { "Siamo sotto assedio! All'armi! Uccidete questo {name}!", "." },
  ["4df269e7ade06f40"] = { "Forse non lo sai, ma oltre a essere un abile sarto, Jormund è anche un ammazzagiganti! Beh, deve aver sentito alcuni di noi scambiarsi storie quando ha urlato di averne uccisi sette in un colpo solo!\n\nDovresti fargli visita al suo negozio, sul lato nord della ⟦Great Forge=Grande Forgia⟧, e vedere se ti racconta la storia!", "." },
  ["4df6683b3161627b"] = { "%s scambia qualche parola sommessa con {name} e <gli/le> consegna un piccolo oggetto.", "." },
})
